"""
Vendor Lexend, the typeface the Digital Leaders logo is drawn in.

The logo SVG contains live text, not outlined paths, and asks for
Lexend-Light and Lexend-Medium. Without the font the browser substitutes
something else; because every tspan carries a hard-coded x position from the
original Illustrator export, substituted glyphs land in the wrong places and
the wordmark reads as though letters are missing ("digi tal", "Ca reers").

Supplying the real font makes the browser lay the text out as designed.
Lexend is licensed under the SIL Open Font License, so it can be embedded.

Weights: 300 (Light) and 500 (Medium) — the two the logo uses.

Usage:
    python fetch_lexend.py        # writes vendor/lexend.css
"""
import base64
import os
import re
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
OUTPUT = os.path.join(HERE, 'lexend.css')

CSS_URL = 'https://fonts.googleapis.com/css2?family=Lexend:wght@300;500&display=swap'
KEEP_SUBSETS = ('latin', 'latin-ext')

UA = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
      '(KHTML, like Gecko) Chrome/120.0 Safari/537.36')


def get(url, binary=False):
    request = urllib.request.Request(url, headers={'User-Agent': UA})
    with urllib.request.urlopen(request, timeout=60) as response:
        payload = response.read()
    return payload if binary else payload.decode('utf-8')


def main():
    css = get(CSS_URL)
    blocks = re.split(r'/\*\s*([\w-]+)\s*\*/', css)
    pairs = list(zip(blocks[1::2], blocks[2::2]))

    rules = []
    total = 0
    for subset, block in pairs:
        if subset not in KEEP_SUBSETS:
            continue
        url_match = re.search(r"url\((https://[^)]+\.woff2)\)", block)
        weight_match = re.search(r'font-weight:\s*(\d+)', block)
        range_match = re.search(r'unicode-range:\s*([^;]+);', block)
        if not (url_match and weight_match):
            continue

        font = get(url_match.group(1), binary=True)
        total += len(font)
        encoded = base64.b64encode(font).decode('ascii')

        # The SVG names the faces "Lexend-Light" / "Lexend-Medium" as well as
        # the family "Lexend", so both spellings are declared.
        family = 'Lexend-Light' if weight_match.group(1) == '300' else 'Lexend-Medium'
        for name in ('Lexend', family):
            rules.append(
                "@font-face {\n"
                "  font-family: '%s';\n"
                "  font-style: normal;\n"
                "  font-weight: %s;\n"
                "  font-display: block;\n"
                "  src: url(data:font/woff2;base64,%s) format('woff2');\n"
                "%s}" % (
                    name, weight_match.group(1), encoded,
                    '  unicode-range: %s;\n' % range_match.group(1) if range_match else ''
                ))
        print('  %-10s weight %s  %5.1f KB' % (subset, weight_match.group(1), len(font) / 1024))

    if not rules:
        raise SystemExit('no Lexend faces found -- the CSS format may have changed')

    header = ('/* Lexend (SIL Open Font License) — the Digital Leaders wordmark\n'
              '   is set in it. Without this the logo SVG substitutes another\n'
              '   face and its hard-coded glyph positions fall apart.\n'
              '   Generated by vendor/fetch_lexend.py. */\n\n')
    with open(OUTPUT, 'w', encoding='utf-8') as handle:
        handle.write(header + '\n\n'.join(rules) + '\n')

    print('\nwrote %s (%.1f KB of font data, %.1f KB encoded)'
          % (OUTPUT, total / 1024, os.path.getsize(OUTPUT) / 1024))


if __name__ == '__main__':
    main()
